<div class="row justify-content-center"><div class="col-lg-8"><div class="card custom-card"><div class="card-header"><h5 class="mb-0">FMS Storage Settings</h5></div><div class="card-body"><h6>Account</h6><dl class="row"><dt class="col-sm-4">Username</dt><dd class="col-sm-8"><?= esc((string)($storageUser['fms_storage_username']??'')) ?></dd><dt class="col-sm-4">Nama</dt><dd class="col-sm-8"><?= esc((string)($storageUser['fms_storage_full_name']??'')) ?></dd><dt class="col-sm-4">Role</dt><dd class="col-sm-8"><?= !empty($storageUser['fms_storage_super_admin'])?'Super Administrator':'Storage User' ?></dd></dl><hr><h6>Ganti Password</h6><form id="fmsStoragePassword"><div class="mb-3"><input class="form-control" name="current_password" type="password" placeholder="Password saat ini" required></div><div class="mb-3"><input class="form-control" name="new_password" type="password" minlength="12" placeholder="Password baru, minimal 12 karakter" required></div><button class="btn btn-primary">Simpan Password</button></form><div id="fmsStoragePasswordMessage" class="mt-3"></div></div></div></div></div>
<script>document.getElementById('fmsStoragePassword').addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=await fetch('<?= esc(site_url('api/v1/storage/profile/password'),'js') ?>',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const j=await r.json();document.getElementById('fmsStoragePasswordMessage').textContent=j.message|| (j.status?'Password tersimpan.':'Gagal menyimpan password.');});</script>
